export default function Pricing() {
	useEffect(() => {
		const pricingSection = document.querySelector('.framer-13e87qe')
		if (!pricingSection) return

		// Apply interactive hover & shimmer to pricing cards
		const cards = pricingSection.querySelectorAll('.framer-px4sk5, .framer-1dympnd, .framer-1rpbdej')
		cards.forEach((card) => {
			card.classList.add('pricing-card-interactive')
		})

		// Apply shimmer to the Most Popular tier
		const popularCards = pricingSection.querySelectorAll('.framer-1dympnd')
		popularCards.forEach((card) => {
			card.classList.add('most-popular-shimmer')
			const tag = card.querySelector('.framer-953f82')
		if (tag) tag.classList.add('most-popular-shimmer')
		})
	}, [])

	return <section id="pricing" className="framer-13e87qe" data-framer-name="Pricing" dangerouslySetInnerHTML={{ __html: content }} />
}
